#include <vector>
#include <iostream>

int main() {
    std::vector<int> numbers = {1, 2, 3, 4, 5};  // Initialize a vector with elements
    for (const auto& num : numbers) {  // Iterate using range-based for loop with const reference
        std::cout << num << ' ';  // Output each element
    }
    // The loop automatically handles the range without manual indexing
    return 0;
}
